dict(tf=[('完整','这份三页，另一份少一页。','This has three pages; the other lacks one.','The other has all three pages.',False,'One is missing.'),('达到','日期还没核对，任务未完成。','The date is unchecked and the task unfinished.','The task remains incomplete.',True,'未完成 states the result.')],reply=[('标题','标题一样，内容也一定一样吗？','Do identical titles guarantee identical content?',['不一定，要看内容。','一定，标题就是所有证据。','完成就是打不开。'],0,'Check the actual contents.'),('保留','修改之前，原件怎么办？','What about the original before revision?',['先保留，修改后再核对。','先删，保证都正确。','把日期当颜色。'],0,'Retain the source for comparison.')],fill=[('保存','修改后保存，再打开检查。','After revision, save and reopen to check.'),('具体','请说具体哪一页。','Specify which page.')],match=[('记录',[('找到文件。','Successfully find the file.'),('记住日期。','Retain the date.'),('拿走原件。','Take the original away.')]),('达到',[('时间结束，任务未完成。','Time ended with the task unfinished.'),('文件完整，有三页。','The file is intact with three pages.'),('内容有错误。','The content has an error.')])]),
